127	// seriesID 是序列的规范身份，标签书写顺序不影响身份。
128	type seriesID struct {
129		name string
130		// sig 为排序后标签键值对的长度前缀拼接，避免不同写法产生碰撞。
131		sig string
132	}
133	
134	type storedSeries struct {
135		ref    SeriesRef
136		points map[int64]float64
137	}
