144	// cloneLabels 返回标签集合的独立副本；空标签仍复制为非 nil 的空集合，
145	// 调用方对副本的增删改不影响存储中的序列身份。
146	func cloneLabels(labels map[string]string) map[string]string {
147		out := make(map[string]string, len(labels))
148		for k, v := range labels {
149			out[k] = v
150		}
151		return out
152	}
153	
154	func sortedKeys(m map[string]string) []string {
155		keys := make([]string, 0, len(m))
156		for k := range m {
157			keys = append(keys, k)
158		}
159		sort.Strings(keys)
160		return keys
161	}
162	
163	func makeSeriesID(name string, labels map[string]string) seriesID {
164		var b strings.Builder
165		for _, k := range sortedKeys(labels) {
166			v := labels[k]
167			fmt.Fprintf(&b, "%d:%s;%d:%s;", len(k), k, len(v), v)
168		}
169		return seriesID{name: name, sig: b.String()}
170	}
