213	// ProcessLine 处理一行非空输入：JSON 数组为写入批次，JSON 对象为查询/操作。
214	// 成功时返回非 nil 的 *BatchResult、*QueryResult、*QueryPointsResult 或
215	// *QueryWindowsResult 且错误为 nil；任何失败都返回真正的 nil 结果与 *LineError，
216	// 调用方直接比较 result == nil 即可判定失败，无须先区分结果类型。空写入数组与
217	// 无命中的查询仍是成功，结果不为 nil。
218	func (s *MetricStore) ProcessLine(line string) (any, *LineError) {
219		top, ok, lerr := decodeTopValue(line)
220		if lerr != nil {
221			return nil, lerr
222		}
223		switch ok {
224		case '[':
225			var items []json.RawMessage
226			if err := json.Unmarshal(top, &items); err != nil {
227				return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
228			}
229			// 不能把 *BatchResult 直接装进 any 返回：失败时它是带类型的 nil 指针，
230			// 接口值非 nil，调用方会把失败误判为有结果。
231			batch, lerr := s.ingestItems(items)
232			if lerr != nil {
233				return nil, lerr
234			}
235			return batch, nil
236		case '{':
237			// 同上：失败时不能把带类型 nil 的结果指针装进 any。
238			// 统一入口不限制 op：wantOp 传空，由请求自身的 op 选择查询功能。
239			return s.runQueryObject(top, "")
240		default:
241			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
242		}
243	}
244	
245	// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
246	// 失败返回 *LineError，此时此前各批数据保留、本批不写入任何数据。
247	func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
248		top, ok, lerr := decodeTopValue(line)
249		if lerr != nil {
250			return nil, lerr
251		}
252		if ok != '[' {
253			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples"}
254		}
255		var items []json.RawMessage
256		if err := json.Unmarshal(top, &items); err != nil {
257			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
258		}
259		return s.ingestItems(items)
260	}
