273	// QueryWindowsLine 解析并执行一行 op 为 "query_windows" 的固定时间窗口均值查询
274	// 对象。成功返回 QueryWindowsResult；查询只读，不改变存储。
275	func (s *MetricStore) QueryWindowsLine(line string) (*QueryWindowsResult, *LineError) {
276		res, lerr := s.queryLineForOp(line, "query_windows")
277		if lerr != nil {
278			return nil, lerr
279		}
280		return res.(*QueryWindowsResult), nil
281	}
