993	// pointStats 是区间统计（query）与固定窗口统计（query_windows）共用的
994	// 点数与均值累计器：逐点累计个数与精确有理数总和。写入侧已保证值有限，
995	// SetFloat64 对有限值是精确的，因此求和与点的提交顺序、批次划分无关，
996	// 正负大数抵消后的微小余量不会丢失，总和超出 float64 有限范围时均值仍有限。
997	// 两种统计只在“哪些点归入哪一组”上不同，点数与均值规则统一由这里维护：
998	// 区间统计为整条序列使用一个累计器，固定窗口统计为每个实际有点的窗口各建
999	// 一个独立累计器，窗口之间天然互不携带点数与数值，不需要在窗口间清空复用。
1000	type pointStats struct {
1001		count int
1002		sum   *big.Rat
1003		tmp   *big.Rat
1004	}
1005	
1006	func newPointStats() *pointStats {
1007		return &pointStats{sum: new(big.Rat), tmp: new(big.Rat)}
1008	}
1009	
1010	// add 把一个实际保存的 float64 采样值计入统计。
1011	func (a *pointStats) add(v float64) {
1012		a.count++
1013		a.sum.Add(a.sum, a.tmp.SetFloat64(v))
1014	}
1015	
1016	// average 返回精确算术平均舍入到最近可表示 float64 的结果（正中取偶；
1017	// 精确为零时返回 +0）。调用方保证至少 add 过一次。不改动累计状态。
1018	func (a *pointStats) average() float64 {
1019		return ratToFloat64NearestEven(new(big.Rat).Quo(a.sum, a.tmp.SetInt64(int64(a.count))))
1020	}
