1057	// runQueryPoints 只读列出已成功提交的采样明细：name 精确、标签子集、
1058	// [start,end] 闭区间，与 runQuery 共用同一套序列筛选与 organizeSeries 整理
1059	// 规则，因此序列排列次序与均值查询一致。每条命中序列保留完整指标名与完整
1060	// 标签集合，points 按时间戳升序列出区间内的 timestamp 与 value，不附加
1061	// count 或 average；区间内没有点的序列不列出，没有任何命中时 series 为
1062	// 空数组。时间戳以 int64 比较与输出，保留整数精度；value 是实际存储的
1063	// float64。查询只读，不改变采样值或写入计数。
1064	func (s *MetricStore) runQueryPoints(q parsedQuery) *QueryPointsResult {
1065		organized := organizeSeries(s.matchSeries(q))
1066	
1067		out := make([]QueryPointsSeries, 0, len(organized))
1068		for _, entry := range organized {
1069			points := seriesPointsInRange(entry.sr, q.start, q.end)
1070			if len(points) == 0 {
1071				continue
1072			}
1073			out = append(out, QueryPointsSeries{
1074				Name:   entry.ref.Name,
1075				Labels: entry.ref.Labels,
1076				Points: points,
1077			})
1078		}
1079		return &QueryPointsResult{Status: "ok", Op: "query_points", Series: out}
1080	}
