11	//
12	//   - 不同的十进制写法转换成同一个存储值（如 9007199254740992 与
13	//     9007199254740993、5e-324 与 4.9406564584124654e-324）：视为重复，
14	//     成功忽略并计入 duplicates，不新增点、不改变查询统计。
15	//   - 相邻但仍可区分的可表示值（如 9007199254740992 与 9007199254740994、
16	//     5e-324 与 1e-323）：必须视为冲突，整批拒绝，conflict 中的
17	//     existing/submitted 都是转换后的实际存储值。
18	//
19	// 规则在同一数组内与跨成功批次提交时一致；正数、负数与接近零的次正规值
20	// 遵循同一条规则。
21	
22	// TestFloat64DedupEquivalentSpellingsCrossBatch 覆盖跨批次提交：
23	// 同一位置先写入 2^53，随后以转换后相等的另一种写法（9007199254740993、
24	// 9007199254740992.5、9.007199254740992e15）再提交，全部成功忽略；
25	// added 为 0、duplicates 按被忽略的提交次数计，快照仍只有原来的一个点，
26	// 查询的 count 与 average 均不受影响。
27	func TestFloat64DedupEquivalentSpellingsCrossBatch(t *testing.T) {
28		store := NewMetricStore()
29		res := mustOK(t, store, `[{"name":"m","timestamp":1000,"value":9007199254740992}]`)
30		if res.Added != 1 || res.Duplicates != 0 {
31			t.Fatalf("initial write counts = %d/%d, want 1/0", res.Added, res.Duplicates)
32		}
33	
34		// 9007199254740993 超出 2^53 的精确表示范围，转换后与 9007199254740992 相同。
35		res = mustOK(t, store, `[{"name":"m","timestamp":1000,"value":9007199254740993}]`)
36		if res.Added != 0 || res.Duplicates != 1 {
37			t.Fatalf("9007199254740993 counts = %d/%d, want 0/1", res.Added, res.Duplicates)
38		}
39		if len(res.Series) != 1 || len(res.Series[0].Points) != 1 {
40			t.Fatalf("snapshot after duplicate = %+v, want still one point", res.Series)
41		}
42		if p := res.Series[0].Points[0]; p.Timestamp != 1000 || p.Value != 9007199254740992.0 {
43			t.Fatalf("stored point = %+v, want ts=1000 value=9007199254740992", p)
44		}
45	
46		// 9007199254740992.5 按最近偶数舍入到 2^53；9.007199254740992e15 是同一值的
47		// 科学计数写法。两种写法各自提交一次，duplicates 只统计本批。
48		res = mustOK(t, store, `[
49			{"name":"m","timestamp":1000,"value":9007199254740992.5},
50			{"name":"m","timestamp":1000,"value":9.007199254740992e15}
51		]`)
52		if res.Added != 0 || res.Duplicates != 2 {
53			t.Fatalf("two equivalent spellings counts = %d/%d, want 0/2", res.Added, res.Duplicates)
54		}
55	
56		// 被忽略的重复不增加 count、不改变 average。
57		q := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":2000}`)
58		if len(q.Series) != 1 || q.Series[0].Count != 1 || q.Series[0].Average != 9007199254740992.0 {
59			t.Fatalf("query after duplicates = %+v, want count=1 average=9007199254740992", q.Series)
60		}
61	}
62	
63	// TestFloat64DedupAdjacentValuesConflict 覆盖相邻可表示值：
64	// 2^53 处相邻的可表示值间隔为 2，9007199254740994 必须与 9007199254740992 区分；
65	// 提交的原始文本本身不可表示（9007199254740993.5）时，conflict 中的 submitted
66	// 也是转换后的存储值 9007199254740994，而不是原始文本或“接近即等”的合并结果。
67	func TestFloat64DedupAdjacentValuesConflict(t *testing.T) {
68		store := NewMetricStore()
69		mustOK(t, store, `[{"name":"m","timestamp":1000,"value":9007199254740992}]`)
70	
71		lerr := mustFail(t, store, `[{"name":"m","timestamp":1000,"value":9007199254740994}]`)
72		if lerr.Index != 1 || lerr.Conflict == nil {
73			t.Fatalf("expected conflict at index 1, got %+v", lerr)
74		}
75		c := lerr.Conflict
76		if c.Timestamp != 1000 || c.Existing != 9007199254740992.0 || c.Submitted != 9007199254740994.0 {
77			t.Fatalf("conflict detail = %+v, want existing=9007199254740992 submitted=9007199254740994", c)
78		}
79		if !strings.Contains(lerr.Error, "9.007199254740992e+15") ||
80			!strings.Contains(lerr.Error, "9.007199254740994e+15") {
81			t.Fatalf("error reason must name the stored values, got %q", lerr.Error)
82		}
83	
84		// 原始文本 9007199254740993.5 不可表示，舍入后为 9007199254740994：
85		// 与已存的 9007199254740992 冲突，submitted 是转换后的存储值。
86		lerr = mustFail(t, store, `[{"name":"m","timestamp":1000,"value":9007199254740993.5}]`)
87		if lerr.Conflict == nil || lerr.Conflict.Submitted != 9007199254740994.0 {
88			t.Fatalf("submitted must be the stored float64 9007199254740994, got %+v", lerr.Conflict)
89		}
90	
91		// 1 与比它大的下一个可表示值也必须区分，不能因为接近而合并。
92		store2 := NewMetricStore()
93		mustOK(t, store2, `[{"name":"m","timestamp":1,"value":1}]`)
94		lerr = mustFail(t, store2, `[{"name":"m","timestamp":1,"value":1.0000000000000002}]`)
95		if lerr.Conflict == nil || lerr.Conflict.Existing != 1 || lerr.Conflict.Submitted != 1.0000000000000002 {
96			t.Fatalf("adjacent values near 1 must conflict, got %+v", lerr.Conflict)
97		}
98	
99		// 冲突整批拒绝：此前写入的原值不变。
100		q := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":2000}`)
101		if len(q.Series) != 1 || q.Series[0].Count != 1 || q.Series[0].Average != 9007199254740992.0 {
102			t.Fatalf("query after rejected conflicts = %+v, want original value intact", q.Series)
103		}
104	}
105	
106	// TestFloat64DedupNegativeValues 确认负数遵循同一规则：
107	// -9007199254740993 转换后与 -9007199254740992 相同（重复），
108	// -9007199254740994 是相邻可表示值（冲突）。
109	func TestFloat64DedupNegativeValues(t *testing.T) {
110		store := NewMetricStore()
111		mustOK(t, store, `[{"name":"m","timestamp":1,"value":-9007199254740992}]`)
112	
113		res := mustOK(t, store, `[{"name":"m","timestamp":1,"value":-9007199254740993}]`)
114		if res.Added != 0 || res.Duplicates != 1 {
115			t.Fatalf("-9007199254740993 counts = %d/%d, want 0/1", res.Added, res.Duplicates)
116		}
117	
118		lerr := mustFail(t, store, `[{"name":"m","timestamp":1,"value":-9007199254740994}]`)
119		if lerr.Conflict == nil ||
120			lerr.Conflict.Existing != -9007199254740992.0 || lerr.Conflict.Submitted != -9007199254740994.0 {
121			t.Fatalf("negative conflict detail = %+v", lerr.Conflict)
122		}
123	
124		q := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":10}`)
125		if len(q.Series) != 1 || q.Series[0].Count != 1 || q.Series[0].Average != -9007199254740992.0 {
126			t.Fatalf("query = %+v, want count=1 average=-9007199254740992", q.Series)
127		}
128	}
129	
130	// TestFloat64DedupSubnormalValues 确认接近零的有限数值也按存储值判定：
131	// 5e-324 与 4.9406564584124654e-324 是最小正次正规值的两种写法（重复），
132	// 1e-323 转换为下一个次正规值（冲突），不能因为数值很小就合并。
133	func TestFloat64DedupSubnormalValues(t *testing.T) {
134		store := NewMetricStore()
135		mustOK(t, store, `[{"name":"m","timestamp":1,"value":5e-324}]`)
136	
137		res := mustOK(t, store, `[{"name":"m","timestamp":1,"value":4.9406564584124654e-324}]`)
138		if res.Added != 0 || res.Duplicates != 1 {
139			t.Fatalf("4.9406564584124654e-324 counts = %d/%d, want 0/1", res.Added, res.Duplicates)
140		}
141	
142		lerr := mustFail(t, store, `[{"name":"m","timestamp":1,"value":1e-323}]`)
143		if lerr.Conflict == nil || lerr.Conflict.Existing != 5e-324 || lerr.Conflict.Submitted != 1e-323 {
144			t.Fatalf("subnormal conflict detail = %+v, want existing=5e-324 submitted=1e-323", lerr.Conflict)
145		}
146	
147		q := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":10}`)
148		if len(q.Series) != 1 || q.Series[0].Count != 1 || q.Series[0].Average != 5e-324 {
149			t.Fatalf("query = %+v, want count=1 average=5e-324", q.Series)
150		}
151	}
152	
153	// TestFloat64DedupEquivalentSpellingsWithinBatch 覆盖同一数组内：
154	// 此前不存在的位置在本批先出现、随后以等值的另一种写法再出现时，
155	// 只新增一个点，duplicates 按本批被忽略的提交次数计算。
156	func TestFloat64DedupEquivalentSpellingsWithinBatch(t *testing.T) {
157		store := NewMetricStore()
158		res := mustOK(t, store, `[
159			{"name":"m","timestamp":1,"value":9007199254740992},
160			{"name":"m","timestamp":1,"value":9007199254740993},
161			{"name":"m","timestamp":1,"value":9.007199254740992e15}
162		]`)
163		if res.Added != 1 || res.Duplicates != 2 {
164			t.Fatalf("counts = %d/%d, want 1/2", res.Added, res.Duplicates)
165		}
166		if len(res.Series) != 1 || len(res.Series[0].Points) != 1 ||
167			res.Series[0].Points[0].Value != 9007199254740992.0 {
168			t.Fatalf("snapshot = %+v, want a single stored point 9007199254740992", res.Series)
169		}
170	
171		// 次正规值在同一数组内同样只新增一个点。
172		store2 := NewMetricStore()
173		res = mustOK(t, store2, `[
174			{"name":"m","timestamp":1,"value":5e-324},
175			{"name":"m","timestamp":1,"value":4.9406564584124654e-324}
176		]`)
177		if res.Added != 1 || res.Duplicates != 1 || len(res.Series[0].Points) != 1 {
178			t.Fatalf("subnormal within-batch = %+v, want added=1 duplicates=1 one point", res)
179		}
180	}
181	
182	// TestFloat64DedupWithinBatchConflictUsesEarlierBatchValue 覆盖同一数组内的冲突：
183	// 位置此前不存在，本批先出现一个值、随后出现转换后不同的值时整批拒绝，
184	// conflict 中的 existing 是本批较早的值，两个点都不保留。
185	func TestFloat64DedupWithinBatchConflictUsesEarlierBatchValue(t *testing.T) {
186		store := NewMetricStore()
187		lerr := mustFail(t, store, `[
188			{"name":"m","timestamp":1,"value":9007199254740992},
189			{"name":"m","timestamp":1,"value":9007199254740994}
190		]`)
191		if lerr.Index != 2 || lerr.Conflict == nil {
192			t.Fatalf("expected conflict at index 2, got %+v", lerr)
193		}
194		c := lerr.Conflict
195		if c.Existing != 9007199254740992.0 || c.Submitted != 9007199254740994.0 {
196			t.Fatalf("existing must be the earlier in-batch value, got %+v", c)
197		}
198		// 两个点都不保留：存储仍为空。
199		if got := len(mustOK(t, store, `[]`).Series); got != 0 {
200			t.Fatalf("rejected batch must leave no points, series count = %d", got)
201		}
202	
203		// 次正规值版本：5e-324 与 1e-323 是相邻可表示值，本批冲突同样整批拒绝。
204		lerr = mustFail(t, store, `[
205			{"name":"m","timestamp":2,"value":5e-324},
206			{"name":"m","timestamp":2,"value":1e-323}
207		]`)
208		if lerr.Index != 2 || lerr.Conflict == nil ||
209			lerr.Conflict.Existing != 5e-324 || lerr.Conflict.Submitted != 1e-323 {
210			t.Fatalf("subnormal within-batch conflict = %+v", lerr)
211		}
212		if got := len(mustOK(t, store, `[]`).Series); got != 0 {
213			t.Fatalf("rejected subnormal batch must leave no points, series count = %d", got)
214		}
215	}
216	
217	// TestFloat64DedupConflictSkipsEarlierAddsInBatch 覆盖位置已存在时的冲突：
218	// 冲突保留此前的值，本批排在冲突点前面的合法新增点也不提交；
219	// 失败后的查询仍看到原值，后续合法输入继续处理。
220	func TestFloat64DedupConflictSkipsEarlierAddsInBatch(t *testing.T) {
221		store := NewMetricStore()
222		mustOK(t, store, `[{"name":"m","timestamp":1000,"value":9007199254740992}]`)
223	
224		// 第一个点是合法新增（等值写法 9007199254740993 与已存值相同，是重复），
225		// 第二个点才是相邻可表示值的冲突：整批拒绝，index 指向冲突点。
226		lerr := mustFail(t, store, `[
227			{"name":"m","timestamp":2000,"value":2},
228			{"name":"m","timestamp":1000,"value":9007199254740993},
229			{"name":"m","timestamp":1000,"value":9007199254740994}
230		]`)
231		if lerr.Index != 3 || lerr.Conflict == nil {
232			t.Fatalf("expected conflict at index 3, got %+v", lerr)
233		}
234		if lerr.Conflict.Existing != 9007199254740992.0 || lerr.Conflict.Submitted != 9007199254740994.0 {
235			t.Fatalf("conflict must keep the previously stored value, got %+v", lerr.Conflict)
236		}
237	
238		// 排在冲突点前面的合法新增点（ts=2000）也没有提交。
239		q := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":3000}`)
240		if len(q.Series) != 1 || q.Series[0].Count != 1 || q.Series[0].Average != 9007199254740992.0 {
241			t.Fatalf("query after failed batch = %+v, want only the original point", q.Series)
242		}
243	
244		// 后续合法输入继续处理：ts=2000 现在可以写入。
245		res := mustOK(t, store, `[{"name":"m","timestamp":2000,"value":2}]`)
246		if res.Added != 1 || res.Duplicates != 0 {
247			t.Fatalf("counts after recovery = %d/%d, want 1/0", res.Added, res.Duplicates)
248		}
249		// 成功快照展示全部已提交数据（含此前批次写入的旧点）。
250		if len(res.Series) != 1 || len(res.Series[0].Points) != 2 {
251			t.Fatalf("snapshot = %+v, want both committed points", res.Series)
252		}
253		q = mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":3000}`)
254		// (9007199254740992 + 2) / 2 = 4503599627370497，精确可表示。
255		if len(q.Series) != 1 || q.Series[0].Count != 2 || q.Series[0].Average != 4503599627370497.0 {
256			t.Fatalf("query after recovery = %+v, want count=2 average=4503599627370497", q.Series)
257		}
258	}
