1	package main
2	
3	import (
4		"bytes"
5		"strings"
6		"testing"
7	)
8	
9	// 端到端回归保障：数值去重与冲突判定以实际存储的有限 float64 值为准，
10	// 不按 JSON 数字的原始文本比较，也不把数值接近当成相等。
11	//
12	//   - 9007199254740993 等写法转换后与已存的 9007199254740992 相同：
13	//     成功忽略，added 为 0、duplicates 为 1，快照仍只有原来的一个点，
14	//     查询的 count 与 average 不变。
15	//   - 9007199254740994 是相邻可表示值：整批冲突拒绝，错误原因与 conflict
16	//     中的 existing、submitted 都是转换后的实际存储值。
17	//   - 次正规值同理：5e-324 与 4.9406564584124654e-324 相等（重复），
18	//     1e-323 不同（冲突），不能因为数值很小就合并。
19	//
20	// 输入中出现过失败行，命令最终以非零退出码结束；失败批次后的查询仍看到
21	// 此前的原值，后续合法输入继续处理。
22	func TestRunIngestFloat64ValueDedupEndToEnd(t *testing.T) {
23		input := strings.Join([]string{
24			// 行 1：写入 2^53（精确可表示）。
25			`[{"name":"m","timestamp":1000,"value":9007199254740992}]`,
26			// 行 2：9007199254740993 转换后与已存值相同 → 重复，成功忽略。
27			`[{"name":"m","timestamp":1000,"value":9007199254740993}]`,
28			// 行 3：9007199254740994 是相邻可表示值 → 冲突，整批拒绝。
29			`[{"name":"m","timestamp":1000,"value":9007199254740994}]`,
30			// 行 4：查询仍只见原值，count=1、average=9007199254740992。
31			`{"op":"query","name":"m","start":0,"end":2000}`,
32			// 行 5：次正规值的两种等价写法同批出现，只新增一个点。
33			`[{"name":"m","timestamp":2000,"value":5e-324},{"name":"m","timestamp":2000,"value":4.9406564584124654e-324}]`,
34			// 行 6：1e-323 与已存的 5e-324 是相邻可表示值 → 冲突。
35			`[{"name":"m","timestamp":2000,"value":1e-323}]`,
36			// 行 7：查询两个点，次正规值不被合并也不被冲刷。
37			`{"op":"query","name":"m","start":0,"end":2000}`,
38		}, "\n")
39	
40		var out bytes.Buffer
41		code := runIngest(strings.NewReader(input), &out)
42		if code == 0 {
43			t.Fatalf("exit code = 0, want non-zero because conflict lines occurred")
44		}
45	
46		lines := strings.Split(strings.TrimRight(out.String(), "\n"), "\n")
47		if len(lines) != 7 {
48			t.Fatalf("got %d output lines, want 7: %v", len(lines), lines)
49		}
50	
51		// 行 1：成功新增一个点。
52		if m := decodeResultLine(t, lines[0]); m["status"] != "ok" ||
53			m["added"].(float64) != 1 || m["duplicates"].(float64) != 0 {
54			t.Fatalf("line 1 = %v, want added=1 duplicates=0", m)
55		}
56	
57		// 行 2：等价写法被忽略，快照仍只有原来的一个点，值是存储的 9007199254740992。
58		m := decodeResultLine(t, lines[1])
59		if m["status"] != "ok" || m["added"].(float64) != 0 || m["duplicates"].(float64) != 1 {
60			t.Fatalf("line 2 = %v, want added=0 duplicates=1", m)
