func TestRunIngestEndToEnd(t *testing.T) {
	input := strings.Join([]string{
		`[{"name":"cpu","timestamp":1000,"value":1}]`, // 行 1：成功
		``,         // 行 2：空白行，无输出但计行号
		`   `,      // 行 3：空白行
