package darksafe

import (
	"encoding/json"
	"math"
	"testing"
)

func TestZZScratchBoundary(t *testing.T) {
	store := NewMetricStore()
	res, lerr := store.IngestLine(`[{"name":"m","timestamp":1,"value":1.7976931348623157e308}]`)
	if lerr != nil {
		t.Fatalf("57 err: %+v", lerr)
	}
	t.Logf("57 ok added=%d val=%v", res.Added, res.Series[0].Points[0].Value == math.MaxFloat64)

	res, lerr = store.IngestLine(`[{"name":"m","timestamp":1,"value":1.7976931348623158e308}]`)
	if lerr != nil {
		t.Fatalf("58 err: %+v", lerr)
	}
	t.Logf("58 ok added=%d dup=%d", res.Added, res.Duplicates)

	_, lerr = store.IngestLine(`[{"name":"m","timestamp":2,"value":1.7976931348623159e308}]`)
	if lerr == nil {
		t.Fatal("59 should fail")
	}
	b, _ := json.Marshal(lerr)
	t.Logf("59 err: %s", b)

	_, lerr = store.IngestLine(`[{"name":"m","timestamp":3,"value":-1.7976931348623159e308}]`)
	if lerr == nil {
		t.Fatal("-59 should fail")
	}
	b, _ = json.Marshal(lerr)
	t.Logf("-59 err: %s", b)

	// existing finite at position then out-of-range -> field error, not conflict
	_, lerr = store.IngestLine(`[{"name":"m","timestamp":1,"value":1.7976931348623159e308}]`)
	if lerr == nil {
		t.Fatal("59 dup-pos should fail")
	}
	b, _ = json.Marshal(lerr)
	t.Logf("59 at existing pos: %s", b)

	// batch: valid add before, then out-of-range -> whole batch rolled back
	_, lerr = store.IngestLine(`[{"name":"m","timestamp":4,"value":1},{"name":"m","timestamp":5,"value":1.7976931348623159e308}]`)
	b, _ = json.Marshal(lerr)
	t.Logf("mixed batch err: %s", b)
	q, _ := store.QueryLine(`{"op":"query","name":"m","start":0,"end":10}`)
	t.Logf("query after rollback count=%d avg=%v", q.Series[0].Count, q.Series[0].Average == math.MaxFloat64)
}
